SELECT CASE WHEN YEAR(delivered_date) < 2024 THEN 'before_2024' WHEN YEAR(delivered_date) = 2024 THEN '2024' ELSE 'after_2024' END AS delivered_cohort, ROUND(AVG(cost), 2) AS avg_cost FROM shipments WHERE status NOT IN ('LOST', 'IN_TRANSIT', 'DELIVERED') AND (carrier IS NOT NULL OR status IN ('LOST', 'DELIVERED', 'RETURNED')) GROUP BY CASE WHEN YEAR(delivered_date) < 2024 THEN 'before_2024' WHEN YEAR(delivered_date) = 2024 THEN '2024' ELSE 'after_2024' END HAVING ROUND(AVG(cost), 2) >= 58 ORDER BY avg_cost ASC;
